using ContentOS.Domain;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
namespace ContentOS.Infrastructure;

public sealed partial class CoreDbContext
{
    public DbSet<CommerceProduct> CommerceProducts => Set<CommerceProduct>(); public DbSet<CommerceRoute> CommerceRoutes => Set<CommerceRoute>(); public DbSet<CommerceOrder> CommerceOrders => Set<CommerceOrder>(); public DbSet<CommerceDelivery> CommerceDeliveries => Set<CommerceDelivery>(); public DbSet<CommerceEffect> CommerceEffects => Set<CommerceEffect>(); public DbSet<CommerceInstitution> CommerceInstitutions => Set<CommerceInstitution>(); public DbSet<CommerceSeat> CommerceSeats => Set<CommerceSeat>(); public DbSet<CommerceActivity> CommerceActivities => Set<CommerceActivity>(); public DbSet<CommerceAudit> CommerceAudits => Set<CommerceAudit>(); public DbSet<CommerceOffer> CommerceOffers => Set<CommerceOffer>();
    private static readonly Type[] CommerceTypes = [typeof(CommerceProduct), typeof(CommerceRoute), typeof(CommerceOrder), typeof(CommerceDelivery), typeof(CommerceEffect), typeof(CommerceInstitution), typeof(CommerceSeat), typeof(CommerceActivity), typeof(CommerceAudit), typeof(CommerceOffer)];
    private static void ConfigureCommerce(ModelBuilder m)
    {
        foreach (var t in CommerceTypes) { var e = m.Entity(t); e.HasBaseType((Type?)null); e.ToTable(t.Name, "commerce"); e.HasKey("Id"); e.Property("RowVersion").IsRowVersion(); e.HasAlternateKey("Id", "TenantId"); e.HasOne(typeof(Tenant)).WithMany().HasForeignKey("TenantId").OnDelete(DeleteBehavior.Restrict); foreach (var p in e.Metadata.GetProperties().Where(x => x.ClrType == typeof(string))) p.SetMaxLength(p.Name.EndsWith("Json") ? -1 : 200); if (e.Metadata.FindProperty("OperationId") != null) e.HasIndex("TenantId", "OperationId").IsUnique(); if (e.Metadata.FindProperty("UserId") != null) e.HasOne(typeof(CustomerUser)).WithMany().HasForeignKey("UserId", "TenantId").HasPrincipalKey("Id", "TenantId").OnDelete(DeleteBehavior.Restrict); }
        m.Entity<CommerceProduct>().HasIndex(x => new { x.TenantId, x.Key, x.Version }).IsUnique(); m.Entity<CommerceRoute>().HasIndex(x => new { x.TenantId, x.Key, x.Version }).IsUnique(); m.Entity<CommerceRoute>().HasIndex(x => x.TenantId).IsUnique().HasFilter("[Active] = 1");
        m.Entity<CommerceProduct>().HasOne<Universe>().WithMany().HasForeignKey(x => new { x.UniverseId, x.TenantId }).HasPrincipalKey(x => new { x.Id, x.TenantId }).OnDelete(DeleteBehavior.Restrict);
        m.Entity<CommerceProduct>().HasOne<PrivateCreation>().WithMany().HasForeignKey(x => new { x.CreationId, x.TenantId }).HasPrincipalKey(x => new { x.Id, x.TenantId }).OnDelete(DeleteBehavior.Restrict); m.Entity<CommerceProduct>().HasOne<CustomerProduct>().WithMany().HasForeignKey(x => new { x.CustomerProductId, x.TenantId }).HasPrincipalKey(x => new { x.Id, x.TenantId }).OnDelete(DeleteBehavior.Restrict);
        m.Entity<CommerceOrder>().HasOne<CommerceProduct>().WithMany().HasForeignKey(x => new { x.ProductId, x.TenantId }).HasPrincipalKey(x => new { x.Id, x.TenantId }).OnDelete(DeleteBehavior.Restrict); m.Entity<CommerceOrder>().HasOne<CommerceRoute>().WithMany().HasForeignKey(x => new { x.RouteId, x.TenantId }).HasPrincipalKey(x => new { x.Id, x.TenantId }).OnDelete(DeleteBehavior.Restrict); m.Entity<CommerceOrder>().HasOne<CustomerOrder>().WithMany().HasForeignKey(x => new { x.PaymentOrderId, x.TenantId }).HasPrincipalKey(x => new { x.Id, x.TenantId }).OnDelete(DeleteBehavior.Restrict); m.Entity<CommerceOrder>().HasOne<CommerceInstitution>().WithMany().HasForeignKey(x => new { x.InstitutionId, x.TenantId }).HasPrincipalKey(x => new { x.Id, x.TenantId }).OnDelete(DeleteBehavior.Restrict);
        m.Entity<CommerceDelivery>().HasIndex(x => x.OrderId).IsUnique(); m.Entity<CommerceDelivery>().Property(x => x.Cost).HasPrecision(18, 8); m.Entity<CommerceDelivery>().HasOne<CommerceOrder>().WithMany().HasForeignKey(x => new { x.OrderId, x.TenantId }).HasPrincipalKey(x => new { x.Id, x.TenantId }).OnDelete(DeleteBehavior.Restrict); m.Entity<CommerceEffect>().HasIndex(x => x.DeliveryId).IsUnique(); m.Entity<CommerceEffect>().HasOne<CommerceDelivery>().WithMany().HasForeignKey(x => new { x.DeliveryId, x.TenantId }).HasPrincipalKey(x => new { x.Id, x.TenantId }).OnDelete(DeleteBehavior.Restrict);
        m.Entity<CommerceSeat>().HasIndex(x => new { x.TenantId, x.InstitutionId, x.UserId }).IsUnique(); foreach (var t in new[] { typeof(CommerceSeat), typeof(CommerceActivity) }) m.Entity(t).HasOne(typeof(CommerceInstitution)).WithMany().HasForeignKey("InstitutionId", "TenantId").HasPrincipalKey("Id", "TenantId").OnDelete(DeleteBehavior.Restrict);
        m.Entity<CommerceActivity>().HasOne<CustomerProfile>().WithMany().HasForeignKey(x => new { x.ProfileId, x.TenantId }).HasPrincipalKey(x => new { x.Id, x.TenantId }).OnDelete(DeleteBehavior.Restrict);
    }
    private static void ValidateCommerceChange(EntityEntry e)
    {
        if (!CommerceTypes.Contains(e.Entity.GetType())) return; if (e.State == EntityState.Deleted) throw new InvalidOperationException("Retain minimal commercial/seat/effect audit evidence."); if (e.State != EntityState.Modified) return;
        string[] allowed = e.Entity switch { CommerceProduct => ["CustomerProductId", "PackageJson", "Enabled", "UpdatedUtc"], CommerceRoute => ["Active", "Enabled", "UpdatedUtc"], CommerceOrder => ["PaymentOrderId", "State", "EndsUtc", "UpdatedUtc"], CommerceDelivery => ["State", "Lease", "LeaseUntilUtc", "Receipt", "Cost", "Currency", "UpdatedUtc"], CommerceSeat => ["Cohort", "Role", "Enabled", "UpdatedUtc"], _ => [] };
        if (e.Properties.Any(x => x.IsModified && !allowed.Contains(x.Metadata.Name))) throw new InvalidOperationException("Sold versions, original bindings, licenses and institutional evidence are immutable.");
        if (e.Entity is CommerceProduct && e.Property("PackageJson").IsModified && e.Property("PackageJson").CurrentValue != null) throw new InvalidOperationException("Only privacy redaction may change stored licensed content.");
        if (e.Entity is CommerceProduct && e.Property("CustomerProductId").OriginalValue != null && e.Property("CustomerProductId").IsModified) throw new InvalidOperationException("Original catalog price binding cannot change.");
        if (e.Entity is CommerceOrder && e.Property("PaymentOrderId").OriginalValue != null && e.Property("PaymentOrderId").IsModified) throw new InvalidOperationException("Original payment order cannot change.");
    }
}
